import java.io.*;
import java.util.*;

public class HeightAllTheSame {
    public static void main(String args[]) throws Exception {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long M = sc.nextLong();
        long L = sc.nextLong();
        long R = sc.nextLong();

        long total = R - L + 1;
        long E = total / 2 + (total % 2 == 0 && L % 2 == 0 ? 1 : 0);
        long O = total - E;

        long result;
        if ((N * M) % 2 == 1) {
            result = powMod(E + O, N * M);
        } else {
            result = (powMod(E + O, N * M) + powMod(E - O, N * M)) % mod;
            result = (result * modInverse(2)) % mod;
        }
        System.out.println(result);
        sc.close();
    }

    static long mod = 998244353;

    static long modInverse(long x) {
        return powMod(x, mod - 2);
    }

    static long powMod(long base, long exp) {
        long res = 1;
        long b = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = (res * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return res;
    }
}
